mapper.sql:
WHERE ea.is_active = 1

  AND ea.employee_id = #{filter.employeeId}


  AND departments.id = #{filter.departmentId}


  AND positions.id = #{filter.positionId}


  AND egroups.id = #{filter.groupId}


    AND (
        employees.name_en LIKE CONCAT("%", #{filter.searchText}, "%") OR
        employees.name_kh LIKE CONCAT("%", #{filter.searchText}, "%") OR
        employees.employee_code LIKE CONCAT("%", #{filter.searchText}, "%") OR
        employees.telephone LIKE CONCAT("%", #{filter.searchText}, "%")
    )

mapper.select:
		SELECT




    GROUP BY ea.id
    ORDER BY


        ${filter.orderBy}


        ea.id DESC


    LIMIT #{filter.page}, #{filter.rowsPerPage}
